"""Reproduce immutable publication movies and exact decoded-pixel poster strips.
Requires ffmpeg/ffprobe; all source inputs are public assets, no private work.
"""
from pathlib import Path
import hashlib,json,subprocess,io,platform
from PIL import Image,__version__ as pillow_version
R=Path(__file__).resolve().parents[1];A=R/'assets';P='ch15-v2-sarcomere-observed';sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
s=json.loads((A/(P+'-sources.json')).read_text(encoding='utf-8'));figs=[];outputs=[];audits=[]
for c in s['clips']:
 media=A/c['public_file'];assert sha(media)==c['sha256'];key=c['key'];browser=media
 if isinstance(c.get('browser_rendition'),dict):
  browser=A/c['browser_rendition']['file'];subprocess.run(['ffmpeg','-v','error','-y','-i',str(media),'-map','0','-c','copy','-tag:v','hvc1','-map_metadata','-1','-movflags','+faststart',str(browser)],check=True);assert sha(browser)==c['browser_rendition']['sha256'];outputs.append(browser)
 j=json.loads(subprocess.check_output(['ffprobe','-v','error','-select_streams','v:0','-show_frames','-show_entries','frame=pts_time,best_effort_timestamp_time','-of','json',str(media)]));assert len(j['frames'])==116
 fragments=[]
 for sample in c['sample_frames']:
  n=sample['frame'];assert abs(float(j['frames'][n]['pts_time'])-sample['pts_s'])<1e-6
  b=subprocess.check_output(['ffmpeg','-v','error','-i',str(media),'-vf',f'select=eq(n\\,{n})','-vsync','0','-frames:v','1','-f','image2pipe','-c:v','png','-']);im=Image.open(io.BytesIO(b)).convert('RGB');assert im.size==(1920,1080)
  if n==0:
   full=A/(P+'-'+key+'-poster.png');im.save(full);outputs.append(full)
  crop=im.crop(tuple(s['cropping']['rect']));out=A/(P+'-'+key+f'-strip-{n:03d}.png');crop.save(out);outputs.append(out)
  audits.append({'clip':key,'frame':n,'pts_s':sample['pts_s'],'full_decoded_rgb_sha256':hashlib.sha256(im.tobytes()).hexdigest(),'crop_file':out.name,'crop_rgb_sha256':hashlib.sha256(crop.tobytes()).hexdigest(),'crop_sha256':sha(out)})
  fragments.append(f'<p class="frame-label">Frame {n} · source-file PTS {sample["pts_s"]:.6f} s</p><div class="strip" tabindex="0" role="region" aria-label="Scrollable {key} source striation strip frame{n}"><img src="{out.name}" width="1010" height="80" alt="Unchanged source striation detail, {key} frame{n}; repeated dark/light profiles between supports."></div>')
 title='Activation'if key=='activation'else'Deactivation';vname='Video 1'if key=='activation'else'Video 2';mime='video/mp4'
 figures=f'''<figure class="{key}"><h2>{title} · source {vname}</h2><div class="player" id="player-{key}" tabindex="0" role="region" aria-label="Scrollable {title.lower()} source video"><video id="video-{key}" controls playsinline preload="metadata" poster="{P}-{key}-poster.png" data-observed-controls data-observed-name="Rabbit myofibril {title.lower()}"><source src="{browser.name}" type="{mime}">Your browser cannot decode this source movie. <a href="{media.name}">Open/download the original</a>.</video></div><div class="actions"><button data-player="player-{key}" data-player-mode="detail">Striation detail</button><button data-player="player-{key}" data-player-mode="native">Native full frame</button><button data-player="player-{key}" data-player-mode="fit">Fit full frame</button><a href="{media.name}" target="_blank" rel="noopener">Original complete {vname}</a><button data-enlarge="{P}-{key}-poster.png" data-width="1920" data-alt="Complete original {title.lower()} frame0">Enlarge whole frame 0</button><label>Playback speed <select data-local-speed="video-{key}"><option value="0.25">0.25×</option><option value="0.5">0.5×</option><option value="1" selected>1×</option><option value="2">2×</option></select></label></div><p class="help">The initial view pans to the striation band without cropping the media. Native/Fit restores full-frame context. Focus the video region to pan with arrows/Home/End. Controls report source-file seconds; playback rate changes presentation only.</p><div class="strips">{''.join(fragments)}</div><p class="key"><strong>Spatial key:</strong> repeated dark/light profiles are the observed myofibril striation pattern. The myofibril is held between a glass-needle/motor support and reinforced nano-levers. Overall length stays near fixed while individual spacings can change non-uniformly. No new Z-disk, A/I-band, molecular, force-vector or metric-scale label is assigned to these frames.</p><ol><li>Compare frame 0 with frame 58: follow several neighboring striation intervals rather than assuming equal shortening.</li><li>Compare frame 115 with the initial field; these are selected views within the separately published {title.lower()} observation.</li><li>The whole-frame source preserves support context. Individual molecular strokes and NMJ signaling are not visible.</li></ol><p><strong>Timing:</strong> 116 exported frames at 30 fps; source-file PTS 0 to 3.833333 s, stream duration about 3.8666 s including the final-frame dwell. {'The unchanged activation AAC track extends the container to 3.925313 s, so its browser denominator may read 3.93 s.'if key=='activation'else'The HEVC/AAC browser MP4 is a container-only remux of the original MOV; coded packet bytes and frame PTS are preserved. Its container duration rounds to 3.867 s.'} The reviewed source does not specify an acquisition-interval or speed-conversion mapping for these clips; no biological clock is reconstructed.</p><p class="credit">Li, Leonard, Han, Moo &amp; Herzog (2024), <a href="https://doi.org/10.3389/fphys.2023.1242177">Gaining new understanding of sarcomere length non-uniformities in skeletal muscles</a>, {vname}; <a href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0</a>, ©2024 authors. Rabbit psoas isolated myofibrils, rigor-glycerol storage, experimental chamber 20°C, chemically activated at pCa4.0; not intact human nerve-driven contraction. Complete unchanged 1920×1080 publication {'H.264 MP4'if key=='activation'else'HEVC MOV'}; native browser codec support varies. Exact decoded-pixel strip (400,140)–(1410,220), 1010×80; no resampling/contrast change/added bar. At 170 mm print width, about 151 ppi. The two clips remain separate observations, not a matched continuous activation–relaxation cycle. <a href="{P}-sources.json">Specimen, rights and clock record</a> · <a href="{P}-provenance.json">Reproduction/hashes</a>.</p></figure>'''
 figs.append(figures);outputs.append(media)
t=R/'figures/ch15_sarcomere_observed_v2.template.html';h=A/(P+'-reference.html');h.write_text(t.read_text(encoding='utf-8').replace('<!-- CLIP_FIGURES -->','\n'.join(figs)),encoding='utf-8');outputs.append(h)
r={'date':'2026-11-09','status':'Candidate; independent final source/native appearance and actual browser/print review pending, no acceptance inferred','source_record':P+'-sources.json','source_record_sha256':sha(A/(P+'-sources.json')),'source_media_unchanged':s['clips'],'crop':s['cropping'],'frame_audit':audits,'print':s['print'],'assay_limits':s['assay_limits'],'review_basis':'B scoped source/precode approval in work/visual-v2/ch15/sarcomere-source/review-independent-precode.md; no final acceptance inferred','reproduction':{'builder':'figures/ch15_sarcomere_observed_v2.py','builder_sha256':sha(__file__),'template':'figures/ch15_sarcomere_observed_v2.template.html','template_sha256':sha(t),'python':platform.python_version(),'pillow':pillow_version,'ffmpeg':subprocess.check_output(['ffmpeg','-version'],text=True).splitlines()[0],'inputs':'Immutable public original MP4/MOV and sourceJSON/template/sharedcontrols only; no privatework/network; exact frame selection by decodedindex and verifiedPTS'},'shared_dependencies':{n:sha(A/n)for n in ['observed-image-dialog.css','observed-image-dialog.js','observed-video-controls.css','observed-video-controls.js']},'artifacts':{p.name:sha(p)for p in outputs},'pending':['ActualHEVC MP4 browserdecode; if unsupported root authorized losslessVP9 rendition with frame/PTS proof, originalMOV remains','Actual initialdetail/Native/Fit keyboardpan/seek/rate/reset/reducedmotion/pausedstart','Actual source-striation print legibility, source-limited151ppi and coherent twofigure pages','No completeNMJ/excitation-contraction/crossbridgecycle coverage claimed']}
(A/(P+'-provenance.json')).write_text(json.dumps(r,indent=2,ensure_ascii=False)+'\n',encoding='utf-8');print('OBSERVED_SARCOMERE_GALLERY_COMPOSED')
